#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding()]param()
$root='C:\ProgramData\BlueRidge\ServerReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "server-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'server-role-health-report.log') -Append|Out-Null
try{$os=Get-CimInstance Win32_OperatingSystem;if($os.ProductType -eq 1){Write-Warning 'This computer is a workstation, not Windows Server.'};Get-ComputerInfo|Select WindowsProductName,WindowsVersion,OsBuildNumber,CsName,CsDomain,CsDomainRole,OsLastBootUpTime|ConvertTo-Json|Set-Content (Join-Path $d server-summary.json);if(Get-Command Get-WindowsFeature -ErrorAction SilentlyContinue){Get-WindowsFeature|Where Installed|Select Name,DisplayName,FeatureType,InstallState|Export-Csv (Join-Path $d installed-roles-features.csv) -NoTypeInformation};Get-Service|Where{$_.StartType -eq 'Automatic' -and $_.Status -ne 'Running'}|Select Name,DisplayName,Status,StartType|Export-Csv (Join-Path $d failed-automatic-services.csv) -NoTypeInformation;Get-Volume|Where DriveLetter|Select DriveLetter,FileSystem,HealthStatus,@{n='SizeGB';e={[math]::Round($_.Size/1GB,2)}},@{n='FreeGB';e={[math]::Round($_.SizeRemaining/1GB,2)}}|Export-Csv (Join-Path $d volumes.csv) -NoTypeInformation;Get-SmbShare -ErrorAction SilentlyContinue|Export-Csv (Join-Path $d smb-shares.csv) -NoTypeInformation;Get-NetFirewallProfile|Export-Csv (Join-Path $d firewall-profiles.csv) -NoTypeInformation;w32tm /query /status|Out-File (Join-Path $d time-status.txt);Get-WinEvent -FilterHashtable @{LogName='System';StartTime=(Get-Date).AddDays(-2);Level=1,2,3} -ErrorAction SilentlyContinue|Select -First 500 TimeCreated,Id,ProviderName,LevelDisplayName,Message|Export-Csv (Join-Path $d recent-system-events.csv) -NoTypeInformation;if(Get-Service NTDS -ErrorAction SilentlyContinue){dcdiag /v|Out-File (Join-Path $d dcdiag.txt);repadmin /replsummary|Out-File (Join-Path $d replication-summary.txt);repadmin /showrepl|Out-File (Join-Path $d replication-detail.txt)};if(Get-Service DNS -ErrorAction SilentlyContinue){Get-DnsServerZone -ErrorAction SilentlyContinue|Export-Csv (Join-Path $d dns-zones.csv) -NoTypeInformation};if(Get-Service DHCPServer -ErrorAction SilentlyContinue){Get-DhcpServerv4Scope -ErrorAction SilentlyContinue|Export-Csv (Join-Path $d dhcp-scopes.csv) -NoTypeInformation};Write-Host "Server role health bundle: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
